
local function getOrCreateFolder(parent, name)
    local f = parent:FindFirstChild(name)
    if not f then
        f = Instance.new("Folder")
        f.Name = name
        f.Parent = parent
    end
    return f
end

local function setScript(parent, name, className, source)
    local s = parent:FindFirstChild(name)
    if not s or s.ClassName ~= className then
        if s then s:Destroy() end
        s = Instance.new(className)
        s.Name = name
        s.Parent = parent
    end
    s.Source = source
    return s
end

setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "AnalyticsService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: AnalyticsService.lua\n    Server-side telemetry and event logging for gameplay funnels,\n    retention indicators, and balancing metrics.\n]]\n\nlocal AnalyticsService = {\n    Name = \"AnalyticsService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal eventLog: { { Timestamp: number, Event: string, Params: { [string]: any } } } = {}\n\nfunction AnalyticsService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\nend\n\nfunction AnalyticsService:Start()\n    print(\"[PanicShift AnalyticsService] Initialized telemetry pipeline.\")\nend\n\n-- Records a structured telemetry event\nfunction AnalyticsService:LogEvent(eventName: string, params: { [string]: any }): ()\n    local entry = {\n        Timestamp = os.time(),\n        Event = eventName,\n        Params = params or {},\n    }\n\n    table.insert(eventLog, entry)\n    \n    -- Print structured telemetry for development/debugging\n    local details = \"\"\n    for k, v in pairs(entry.Params) do\n        details = details .. string.format(\" %s=%s\", tostring(k), tostring(v))\n    end\n    print(string.format(\"[Telemetry] %s:%s\", eventName, details))\n\n    -- Keep memory footprint capped\n    if #eventLog > 500 then\n        table.remove(eventLog, 1)\n    end\nend\n\nreturn AnalyticsService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "ChallengeService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: ChallengeService.lua\n    Manages daily challenge rotation, tracking, and objective completion.\n]]\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\n\nlocal ChallengeService = {\n    Name = \"ChallengeService\",\n}\n\nlocal services: { [string]: any } = {}\n\nfunction ChallengeService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\nend\n\nfunction ChallengeService:Start()\n    -- Daily challenge tracking ready\nend\n\n-- Checks and resets daily challenge data if day has rolled over\nfunction ChallengeService:VerifyDailyReset(player: Player): ()\n    local dataService = services.DataService\n    if not dataService then\n        return\n    end\n\n    local currentKey = os.date(\"!%Y-%m-%d\")\n    dataService:UpdateProfile(player, function(profile: Types.PlayerProfile)\n        if profile.dailyChallenges.resetKey ~= currentKey then\n            profile.dailyChallenges = {\n                resetKey = currentKey,\n                completed = {},\n                progress = {},\n            }\n        end\n    end)\nend\n\n-- Increments challenge progress for a specific target action\nfunction ChallengeService:IncrementProgress(player: Player, challengeId: string, amount: number): ()\n    local dataService = services.DataService\n    local economyService = services.EconomyService\n    if not dataService or not economyService then\n        return\n    end\n\n    self:VerifyDailyReset(player)\n\n    local profile = dataService:GetProfile(player)\n    if not profile or profile.dailyChallenges.completed[challengeId] then\n        return\n    end\n\n    -- Find challenge definition\n    local challengeDef = nil\n    for _, def in ipairs(Config.DailyChallenges) do\n        if def.Id == challengeId then\n            challengeDef = def\n            break\n        end\n    end\n\n    if not challengeDef then\n        return\n    end\n\n    dataService:UpdateProfile(player, function(prof: Types.PlayerProfile)\n        local current = (prof.dailyChallenges.progress[challengeId] or 0) + amount\n        prof.dailyChallenges.progress[challengeId] = current\n\n        if current >= challengeDef.TargetCount and not prof.dailyChallenges.completed[challengeId] then\n            prof.dailyChallenges.completed[challengeId] = true\n            economyService:AwardCredits(player, challengeDef.CreditReward, \"DailyChallenge_\" .. challengeId)\n            economyService:AwardXp(player, challengeDef.XpReward, \"DailyChallenge_\" .. challengeId)\n        end\n    end)\nend\n\nreturn ChallengeService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "DataService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: DataService.lua\n    Authoritative player data persistence. Implements schema versioning,\n    session caching, exponential backoff retries, corruption prevention,\n    and an in-memory mock store for safe Studio and offline testing.\n]]\n\nlocal DataStoreService = game:GetService(\"DataStoreService\")\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\n\nlocal DATA_STORE_NAME = \"PanicShift_PlayerData_v1\"\nlocal CURRENT_SCHEMA_VERSION = 1\n\nlocal DataService = {\n    Name = \"DataService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal profiles: { [Player]: Types.PlayerProfile } = {}\nlocal failedLoads: { [Player]: boolean } = {}\nlocal playerDataStore: any = nil\nlocal mockDataStore: { [string]: any } = {} -- Safe mock store for Studio/Test mode\n\n-- Constructs the default player profile\nfunction DataService.CreateDefaultProfile(): Types.PlayerProfile\n    return {\n        schemaVersion = CURRENT_SCHEMA_VERSION,\n        credits = 0,\n        xp = 0,\n        level = 1,\n        ownedCosmetics = { \"default_uniform\" },\n        equippedCosmetic = \"default_uniform\",\n        equippedHat = nil,\n        lifetimeStats = {\n            shiftsCompleted = 0,\n            shiftsWon = 0,\n            tasksCompleted = 0,\n            disastersSurvives = 0,\n            spillsCleaned = 0,\n            ordersDelivered = 0,\n        },\n        dailyChallenges = {\n            resetKey = os.date(\"!%Y-%m-%d\"),\n            completed = {},\n            progress = {},\n        },\n        settings = {\n            musicVolume = 0.8,\n            sfxVolume = 0.9,\n            screenShake = true,\n        },\n    }\nend\n\n-- Migrates data between schema versions safely (FR-18)\nfunction DataService.MigrateProfile(data: any): Types.PlayerProfile\n    if typeof(data) ~= \"table\" then\n        return DataService.CreateDefaultProfile()\n    end\n\n    local profile = Utility.DeepCopy(data) :: Types.PlayerProfile\n\n    -- Version 0 -> Version 1 upgrade\n    if not profile.schemaVersion or profile.schemaVersion < 1 then\n        profile.schemaVersion = 1\n        profile.credits = profile.credits or 0\n        profile.xp = profile.xp or 0\n        profile.level = profile.level or 1\n        profile.ownedCosmetics = profile.ownedCosmetics or { \"default_uniform\" }\n        profile.equippedCosmetic = profile.equippedCosmetic or \"default_uniform\"\n        profile.lifetimeStats = profile.lifetimeStats or {\n            shiftsCompleted = 0,\n            shiftsWon = 0,\n            tasksCompleted = 0,\n            disastersSurvives = 0,\n            spillsCleaned = 0,\n            ordersDelivered = 0,\n        }\n        profile.dailyChallenges = profile.dailyChallenges or {\n            resetKey = os.date(\"!%Y-%m-%d\"),\n            completed = {},\n            progress = {},\n        }\n        profile.settings = profile.settings or {\n            musicVolume = 0.8,\n            sfxVolume = 0.9,\n            screenShake = true,\n        }\n    end\n\n    return profile\nend\n\nfunction DataService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\n\n    local success, store = pcall(function()\n        return DataStoreService:GetDataStore(DATA_STORE_NAME)\n    end)\n\n    if success and store then\n        playerDataStore = store\n        print(\"[PanicShift DataService] Successfully connected to live DataStoreService.\")\n    else\n        warn(\"[PanicShift DataService] DataStoreService unavailable. Operating with In-Memory Mock Store.\")\n    end\nend\n\nfunction DataService:Start()\n    -- Profile loading on player join\n    Players.PlayerAdded:Connect(function(player: Player)\n        self:LoadProfile(player)\n    end)\n\n    -- Profile saving on player disconnect\n    Players.PlayerRemoving:Connect(function(player: Player)\n        self:SaveProfile(player)\n        profiles[player] = nil\n        failedLoads[player] = nil\n    end)\nend\n\nfunction DataService:LoadProfile(player: Player): Types.PlayerProfile?\n    local key = string.format(\"Player_%d\", player.UserId)\n    local loadedData: any = nil\n\n    if playerDataStore then\n        local readSuccess, result = Utility.RetryWithBackoff(3, 1.0, function()\n            local s, res = pcall(function()\n                return playerDataStore:GetAsync(key)\n            end)\n            return s, res\n        end)\n\n        if readSuccess then\n            loadedData = result\n        else\n            warn(string.format(\"[PanicShift DataService] Failed to load data for %s (UserId: %d). Enabling safe read-only fallback.\", player.Name, player.UserId))\n            failedLoads[player] = true\n            profiles[player] = DataService.CreateDefaultProfile()\n            self:SyncClient(player)\n            return profiles[player]\n        end\n    else\n        -- Read from safe local mock store\n        loadedData = mockDataStore[key]\n    end\n\n    local finalProfile: Types.PlayerProfile\n    if loadedData then\n        finalProfile = DataService.MigrateProfile(loadedData)\n    else\n        finalProfile = DataService.CreateDefaultProfile()\n    end\n\n    profiles[player] = finalProfile\n    self:SyncClient(player)\n    return finalProfile\nend\n\nfunction DataService:SaveProfile(player: Player): boolean\n    -- Critical Guard: Never overwrite data if initial load failed (FR-16 / NFR-04)\n    if failedLoads[player] then\n        warn(string.format(\"[PanicShift DataService] Save aborted for %s: initial profile read had failed. Preventing corruption overwrite.\", player.Name))\n        return false\n    end\n\n    local profile = profiles[player]\n    if not profile then\n        return false\n    end\n\n    local key = string.format(\"Player_%d\", player.UserId)\n\n    if playerDataStore then\n        local writeSuccess = Utility.RetryWithBackoff(3, 1.0, function()\n            local s, err = pcall(function()\n                playerDataStore:SetAsync(key, profile)\n            end)\n            if not s then\n                warn(\"[PanicShift DataService] DataStore write error:\", err)\n            end\n            return s, nil\n        end)\n        return writeSuccess\n    else\n        -- Save to local mock store\n        mockDataStore[key] = Utility.DeepCopy(profile)\n        return true\n    end\nend\n\nfunction DataService:GetProfile(player: Player): Types.PlayerProfile?\n    return profiles[player]\nend\n\nfunction DataService:UpdateProfile(player: Player, mutator: (profile: Types.PlayerProfile) -> ()): boolean\n    local profile = profiles[player]\n    if not profile then\n        return false\n    end\n\n    mutator(profile)\n    self:SyncClient(player)\n    return true\nend\n\nfunction DataService:SyncClient(player: Player)\n    local profile = profiles[player]\n    if not profile then\n        return\n    end\n\n    local success, remote = pcall(function()\n        return Network.GetRemoteEvent(Constants.Remotes.PLAYER_PROFILE_UPDATED)\n    end)\n    if success and remote then\n        remote:FireClient(player, profile)\n    end\nend\n\nfunction DataService:SaveAll()\n    for _, player in ipairs(Players:GetPlayers()) do\n        self:SaveProfile(player)\n    end\nend\n\n-- Test helper methods for automated validation\nfunction DataService._InjectMockFailure(player: Player)\n    failedLoads[player] = true\nend\n\nfunction DataService._IsSaveBlocked(player: Player): boolean\n    return failedLoads[player] == true\nend\n\nreturn DataService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "DisasterService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: DisasterService.lua\n    The Disaster Director. Manages disaster weighted selection, telegraph countdowns,\n    module lifecycle execution, and guaranteed fail-safe cleanup.\n]]\n\nlocal ServerStorage = game:GetService(\"ServerStorage\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nlocal DisasterService = {\n    Name = \"DisasterService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal disasterModules: { [string]: any } = {}\nlocal activeDisasterId: string? = nil\nlocal activeDisasterModule: any = nil\nlocal activeDisasterContext: Types.DisasterContext? = nil\nlocal disasterStopThread: thread? = nil\n\nfunction DisasterService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\n\n    -- Dynamically locate and register disaster modules\n    local storageFolder = ServerStorage:FindFirstChild(\"PanicShiftStorage\")\n    local modulesFolder = storageFolder and storageFolder:FindFirstChild(\"DisasterModules\") or ServerStorage:FindFirstChild(\"DisasterModules\")\n\n    if modulesFolder then\n        for _, child in ipairs(modulesFolder:GetChildren()) do\n            if child:IsA(\"ModuleScript\") then\n                local success, disasterMod = pcall(function()\n                    return require(child)\n                end)\n                if success and typeof(disasterMod) == \"table\" then\n                    disasterModules[child.Name] = disasterMod\n                else\n                    warn(string.format(\"[PanicShift DisasterService] Failed to load module %s\", child.Name))\n                end\n            end\n        end\n    end\nend\n\nfunction DisasterService:Start()\n    -- Ready for shift disasters\nend\n\n-- Weighted random selection of the next disaster\nfunction DisasterService:SelectNextDisaster(): string?\n    local eligible: { { id: string, weight: number } } = {}\n    local totalWeight = 0\n\n    for id, weight in pairs(Config.Disasters.Weights) do\n        -- Exclude currently active disaster\n        if id ~= activeDisasterId and disasterModules[id] then\n            local mod = disasterModules[id]\n            local canStart = true\n            if typeof(mod.CanStart) == \"function\" then\n                canStart = mod.CanStart()\n            end\n            if canStart then\n                table.insert(eligible, { id = id, weight = weight })\n                totalWeight = totalWeight + weight\n            end\n        end\n    end\n\n    if totalWeight <= 0 or #eligible == 0 then\n        return nil\n    end\n\n    local roll = math.random(1, totalWeight)\n    local accumulated = 0\n    for _, item in ipairs(eligible) do\n        accumulated = accumulated + item.weight\n        if roll <= accumulated then\n            return item.id\n        end\n    end\n\n    return eligible[1].id\nend\n\n-- Initiates a disaster event with telegraphing and scheduled cleanup\nfunction DisasterService:TriggerDisaster(disasterId: string, customDuration: number?): boolean\n    if activeDisasterId then\n        self:StopActiveDisaster()\n    end\n\n    local mod = disasterModules[disasterId]\n    if not mod then\n        warn(string.format(\"[PanicShift DisasterService] Disaster module '%s' not registered!\", disasterId))\n        return false\n    end\n\n    local duration = customDuration or Config.Disasters.Durations[disasterId] or 25\n    local telegraphDuration = Config.Disasters.TelegraphDuration\n\n    local context: Types.DisasterContext = {\n        RoundId = services.RoundService and services.RoundService:GetCurrentRoundId() or \"DevShift\",\n        Duration = duration,\n        SupermarketMap = (services.RoundService and services.RoundService:GetSupermarketMap()) or workspace:FindFirstChild(\"SupermarketMap\") or workspace,\n        Services = services,\n        TelegraphDuration = telegraphDuration,\n    }\n\n    activeDisasterId = disasterId\n    activeDisasterModule = mod\n    activeDisasterContext = context\n\n    -- Broadcast telegraph warning\n    local remote = Network.GetRemoteEvent(Constants.Remotes.DISASTER_STATE_CHANGED)\n    remote:FireAllClients(disasterId, Constants.DisasterStatus.TELEGRAPH, telegraphDuration, {\n        Duration = duration,\n    })\n\n    if services.AnalyticsService then\n        services.AnalyticsService:LogEvent(\"DisasterTelegraph\", { DisasterId = disasterId })\n    end\n\n    -- Run disaster execution in a dedicated task thread\n    disasterStopThread = task.spawn(function()\n        task.wait(telegraphDuration)\n\n        if activeDisasterId ~= disasterId then\n            return -- Was cancelled during telegraph\n        end\n\n        remote:FireAllClients(disasterId, Constants.DisasterStatus.ACTIVE, duration, {})\n\n        -- Protected start execution\n        local startOk, startErr = pcall(function()\n            if typeof(mod.Start) == \"function\" then\n                mod.Start(context)\n            end\n        end)\n\n        if not startOk then\n            warn(string.format(\"[PanicShift DisasterService] Disaster %s Start() errored: %s\", disasterId, tostring(startErr)))\n        end\n\n        task.wait(duration)\n\n        -- Natural expiration\n        if activeDisasterId == disasterId then\n            self:StopActiveDisaster()\n        end\n    end)\n\n    return true\nend\n\n-- Guaranteed safe cleanup of active disaster\nfunction DisasterService:StopActiveDisaster(): ()\n    if not activeDisasterId then\n        return\n    end\n\n    local currentId = activeDisasterId\n    local currentMod = activeDisasterModule\n    local currentCtx = activeDisasterContext\n\n    if disasterStopThread then\n        local threadToCancel = disasterStopThread\n        disasterStopThread = nil\n        if threadToCancel ~= coroutine.running() then\n            pcall(task.cancel, threadToCancel)\n        end\n    end\n\n    activeDisasterId = nil\n    activeDisasterModule = nil\n    activeDisasterContext = nil\n\n    if currentMod and typeof(currentMod.Stop) == \"function\" then\n        local ok, err = pcall(function()\n            currentMod.Stop(currentCtx)\n        end)\n        if not ok then\n            warn(string.format(\"[PanicShift DisasterService] Error during %s Stop(): %s\", currentId, tostring(err)))\n        end\n    end\n\n    local remote = Network.GetRemoteEvent(Constants.Remotes.DISASTER_STATE_CHANGED)\n    remote:FireAllClients(currentId, Constants.DisasterStatus.COMPLETED, 0, {})\n\n    if services.AnalyticsService then\n        services.AnalyticsService:LogEvent(\"DisasterEnded\", { DisasterId = currentId })\n    end\nend\n\nfunction DisasterService:IsDisasterActive(): boolean\n    return activeDisasterId ~= nil\nend\n\nreturn DisasterService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "EconomyService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: EconomyService.lua\n    Server-authoritative wallet and progression manager.\n    Enforces atomic credit/XP modifications, level scaling, and audit logging.\n]]\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\n\nlocal MarketplaceService = game:GetService(\"MarketplaceService\")\n\nlocal EconomyService = {\n    Name = \"EconomyService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal gamePassCache: { [number]: { [number]: boolean } } = {}\n\nfunction EconomyService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\nend\n\nfunction EconomyService:Start()\n    -- Ready for shift operations\nend\n\n-- Checks if a player owns a specific GamePass with caching\nfunction EconomyService:PlayerOwnsPass(player: Player, passId: number): boolean\n    if passId <= 0 then return false end\n    local pCache = gamePassCache[player.UserId]\n    if pCache and pCache[passId] ~= nil then\n        return pCache[passId]\n    end\n    local owns = false\n    pcall(function()\n        owns = MarketplaceService:UserOwnsGamePassAsync(player.UserId, passId)\n    end)\n    if not gamePassCache[player.UserId] then\n        gamePassCache[player.UserId] = {}\n    end\n    gamePassCache[player.UserId][passId] = owns\n    return owns\nend\n\n-- Safely retrieves player wallet balance\nfunction EconomyService:GetBalance(player: Player): number\n    local dataService = services.DataService\n    if not dataService then\n        return 0\n    end\n\n    local profile = dataService:GetProfile(player)\n    return profile and profile.credits or 0\nend\n\n-- Atomically awards credits with logging and GamePass multiplier support\nfunction EconomyService:AwardCredits(player: Player, amount: number, reason: string): boolean\n    if amount <= 0 then\n        return false\n    end\n\n    local dataService = services.DataService\n    if not dataService then\n        return false\n    end\n\n    local finalAmount = amount\n    if reason ~= \"RobuxPurchase\" and not string.find(reason, \"Rollback\") then\n        local doublePass = Config.Monetization and Config.Monetization.GamePasses and Config.Monetization.GamePasses.DoubleCredits\n        if doublePass and doublePass.PassId > 0 and self:PlayerOwnsPass(player, doublePass.PassId) then\n            finalAmount = amount * 2\n        end\n    end\n\n    return dataService:UpdateProfile(player, function(profile: Types.PlayerProfile)\n        profile.credits = profile.credits + finalAmount\n    end)\nend\n\n-- Atomically deducts credits with balance verification\nfunction EconomyService:DeductCredits(player: Player, amount: number): boolean\n    if amount <= 0 then\n        return false\n    end\n\n    local dataService = services.DataService\n    if not dataService then\n        return false\n    end\n\n    local currentBalance = self:GetBalance(player)\n    if currentBalance < amount then\n        return false\n    end\n\n    return dataService:UpdateProfile(player, function(profile: Types.PlayerProfile)\n        profile.credits = profile.credits - amount\n    end)\nend\n\n-- Awards XP and evaluates progressive level-ups\nfunction EconomyService:AwardXp(player: Player, amount: number, reason: string): (boolean, boolean)\n    if amount <= 0 then\n        return false, false\n    end\n\n    local dataService = services.DataService\n    if not dataService then\n        return false, false\n    end\n\n    local didLevelUp = false\n\n    local updated = dataService:UpdateProfile(player, function(profile: Types.PlayerProfile)\n        profile.xp = profile.xp + amount\n\n        -- Check level up thresholds\n        local nextLevelRequirement = Config.Progression.CalculateRequiredXp(profile.level)\n        while profile.xp >= nextLevelRequirement do\n            profile.xp = profile.xp - nextLevelRequirement\n            profile.level = profile.level + 1\n            didLevelUp = true\n            nextLevelRequirement = Config.Progression.CalculateRequiredXp(profile.level)\n        end\n    end)\n\n    if didLevelUp and services.AnalyticsService then\n        local profile = dataService:GetProfile(player)\n        services.AnalyticsService:LogEvent(\"PlayerLevelUp\", {\n            PlayerId = player.UserId,\n            NewLevel = profile and profile.level or 1,\n        })\n    end\n\n    return updated, didLevelUp\nend\n\nreturn EconomyService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "InventoryService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: InventoryService.lua\n    Server-side cosmetic ownership and character loadout verifier.\n]]\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nlocal InventoryService = {\n    Name = \"InventoryService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal rateLimiter: (key: any) -> boolean\n\nfunction InventoryService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\n    rateLimiter = Utility.CreateRateLimiter(Config.RateLimits.EQUIP_MAX_PER_SECOND, 1.0)\nend\n\nfunction InventoryService:Start()\n    local equipFunc = Network.GetRemoteFunction(Constants.Remotes.REQUEST_EQUIP_COSMETIC)\n    equipFunc.OnServerInvoke = function(player: Player, cosmeticId: any, slot: any): Types.NetworkResponse\n        return self:HandleEquipRequest(player, cosmeticId, slot)\n    end\nend\n\n-- Checks if player owns a specific cosmetic\nfunction InventoryService:OwnsCosmetic(player: Player, cosmeticId: string): boolean\n    local dataService = services.DataService\n    if not dataService then\n        return false\n    end\n\n    local profile = dataService:GetProfile(player)\n    if not profile then\n        return false\n    end\n\n    for _, ownedId in ipairs(profile.ownedCosmetics) do\n        if ownedId == cosmeticId then\n            return true\n        end\n    end\n\n    return false\nend\n\n-- Validates and applies character cosmetic equip\nfunction InventoryService:HandleEquipRequest(player: Player, cosmeticId: any, slot: any): Types.NetworkResponse\n    -- Anti-exploit: Rate limit check\n    if not rateLimiter(player.UserId) then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.RATE_LIMITED, \"Equip requests are rate-limited.\")\n    end\n\n    -- Argument validation\n    if typeof(cosmeticId) ~= \"string\" or typeof(slot) ~= \"string\" then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_ARGUMENTS, \"Invalid cosmetic request parameters.\")\n    end\n\n    local itemDef = Config.Cosmetics[cosmeticId]\n    if not itemDef then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_ARGUMENTS, \"Cosmetic item does not exist.\")\n    end\n\n    if not self:OwnsCosmetic(player, cosmeticId) then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.ITEM_NOT_OWNED, \"You do not own this cosmetic.\")\n    end\n\n    local dataService = services.DataService\n    if not dataService then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.PROFILE_NOT_LOADED, \"Profile unavailable.\")\n    end\n\n    local success = dataService:UpdateProfile(player, function(profile: Types.PlayerProfile)\n        if itemDef.Type == \"Uniform\" then\n            profile.equippedCosmetic = cosmeticId\n        elseif itemDef.Type == \"Headwear\" then\n            profile.equippedHat = cosmeticId\n        end\n    end)\n\n    if success then\n        return Utility.CreateSuccessResponse({ EquippedId = cosmeticId, Slot = slot })\n    else\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_STATE, \"Failed to update profile.\")\n    end\nend\n\nreturn InventoryService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "PurchaseService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: PurchaseService.lua\n    Manages in-game cosmetic store transactions and receipt validation.\n    Guarantees atomic credit deduction and prevents duplicate unlocks.\n]]\n\nlocal MarketplaceService = game:GetService(\"MarketplaceService\")\nlocal Players = game:GetService(\"Players\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nlocal PurchaseService = {\n    Name = \"PurchaseService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal rateLimiter: (key: any) -> boolean\n\nfunction PurchaseService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\n    rateLimiter = Utility.CreateRateLimiter(Config.RateLimits.PURCHASE_MAX_PER_SECOND, 1.0)\nend\n\nfunction PurchaseService:Start()\n    local purchaseFunc = Network.GetRemoteFunction(Constants.Remotes.REQUEST_PURCHASE_COSMETIC)\n    purchaseFunc.OnServerInvoke = function(player: Player, cosmeticId: any): Types.NetworkResponse\n        return self:HandlePurchaseRequest(player, cosmeticId)\n    end\n\n    -- Server-authoritative Robux Developer Product Receipt Processing\n    MarketplaceService.ProcessReceipt = function(receiptInfo: { [string]: any }): Enum.ProductPurchaseDecision\n        local playerId = receiptInfo.PlayerId\n        local productId = receiptInfo.ProductId\n        local purchaseId = receiptInfo.PurchaseId\n\n        local player = Players:GetPlayerByUserId(playerId)\n        if not player then\n            return Enum.ProductPurchaseDecision.NotProcessedYet\n        end\n\n        local economyService = services.EconomyService\n        if not economyService then\n            return Enum.ProductPurchaseDecision.NotProcessedYet\n        end\n\n        -- Match productId in Config.Monetization.Products\n        local matchedProduct = nil\n        if Config.Monetization and Config.Monetization.Products then\n            for _, product in pairs(Config.Monetization.Products) do\n                if product.ProductId ~= 0 and product.ProductId == productId then\n                    matchedProduct = product\n                    break\n                end\n            end\n        end\n\n        if matchedProduct then\n            local success = economyService:AwardCredits(player, matchedProduct.Credits, \"RobuxPurchase_\" .. tostring(purchaseId))\n            if success then\n                if services.AnalyticsService then\n                    services.AnalyticsService:LogEvent(\"RobuxProductPurchased\", {\n                        PlayerId = playerId,\n                        ProductId = productId,\n                        CreditsAwarded = matchedProduct.Credits,\n                    })\n                end\n                return Enum.ProductPurchaseDecision.PurchaseGranted\n            else\n                return Enum.ProductPurchaseDecision.NotProcessedYet\n            end\n        end\n\n        return Enum.ProductPurchaseDecision.PurchaseGranted\n    end\nend\n\n-- Processes soft-currency (Store Credits) purchases\nfunction PurchaseService:HandlePurchaseRequest(player: Player, cosmeticId: any): Types.NetworkResponse\n    -- Rate limit protection\n    if not rateLimiter(player.UserId) then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.RATE_LIMITED, \"Purchase requests are throttled.\")\n    end\n\n    if typeof(cosmeticId) ~= \"string\" then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_ARGUMENTS, \"Invalid cosmetic ID.\")\n    end\n\n    local itemDef = Config.Cosmetics[cosmeticId]\n    if not itemDef then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_ARGUMENTS, \"Cosmetic item not found in catalog.\")\n    end\n\n    local inventoryService = services.InventoryService\n    local economyService = services.EconomyService\n    local dataService = services.DataService\n\n    if not inventoryService or not economyService or not dataService then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_STATE, \"Internal services unavailable.\")\n    end\n\n    -- Verify not already owned\n    if inventoryService:OwnsCosmetic(player, cosmeticId) then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_STATE, \"You already own this item.\")\n    end\n\n    -- Verify wallet balance\n    local currentBalance = economyService:GetBalance(player)\n    if currentBalance < itemDef.Price then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INSUFFICIENT_FUNDS, \"Insufficient Store Credits.\")\n    end\n\n    -- Atomic transaction: deduct credits and append to inventory\n    local deductSuccess = economyService:DeductCredits(player, itemDef.Price)\n    if not deductSuccess then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INSUFFICIENT_FUNDS, \"Failed to complete transaction.\")\n    end\n\n    local unlockSuccess = dataService:UpdateProfile(player, function(profile: Types.PlayerProfile)\n        table.insert(profile.ownedCosmetics, cosmeticId)\n    end)\n\n    if unlockSuccess then\n        if services.AnalyticsService then\n            services.AnalyticsService:LogEvent(\"CosmeticPurchased\", {\n                PlayerId = player.UserId,\n                ItemId = cosmeticId,\n                Price = itemDef.Price,\n            })\n        end\n\n        return Utility.CreateSuccessResponse({\n            PurchasedId = cosmeticId,\n            NewBalance = economyService:GetBalance(player),\n        })\n    else\n        -- Rollback in extreme case\n        economyService:AwardCredits(player, itemDef.Price, \"Transaction_Rollback\")\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_STATE, \"Profile unlock write failed.\")\n    end\nend\n\nreturn PurchaseService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "RoundService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: RoundService.lua\n    Authoritative round lifecycle state machine. Manages lobby wait,\n    preparation countdown, main shift quotas, closing rush, results, and resets.\n    Strictly validates allowed state transitions and manages player teleportation.\n]]\n\nlocal Players = game:GetService(\"Players\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nlocal RoundService = {\n    Name = \"RoundService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal currentState: Types.RoundState = \"LOBBY\"\nlocal currentRoundId: string = \"\"\nlocal stateTimer: number = 0\nlocal currentQuota: number = 0\nlocal targetQuota: number = 0\nlocal playerContributions: { [number]: { TasksCompleted: number, CreditsEarned: number, XpEarned: number } } = {}\nlocal disasterTimer: number = 0\nlocal nextDisasterInterval: number = 35\n\n-- State Transition Validation Matrix (FR-02)\nlocal VALID_TRANSITIONS: { [Types.RoundState]: { [Types.RoundState]: boolean } } = {\n    LOBBY = { PREPARATION = true },\n    PREPARATION = { ACTIVE = true, LOBBY = true },\n    ACTIVE = { CLOSING = true, LOBBY = true },\n    CLOSING = { RESULTS = true, LOBBY = true },\n    RESULTS = { RESET = true, LOBBY = true },\n    RESET = { LOBBY = true },\n}\n\nfunction RoundService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\nend\n\nfunction RoundService:Start()\n    currentRoundId = Utility.GenerateUUID()\n    self:ForceState(\"LOBBY\")\n\n    -- Authoritative server tick loop\n    task.spawn(function()\n        while true do\n            self:Tick(1.0)\n            task.wait(1.0)\n        end\n    end)\nend\n\nfunction RoundService:GetCurrentRoundId(): string\n    return currentRoundId\nend\n\nfunction RoundService:GetState(): Types.RoundState\n    return currentState\nend\n\nfunction RoundService:GetTimerRemaining(): number\n    return stateTimer\nend\n\nfunction RoundService:GetQuotaProgress(): (number, number)\n    return currentQuota, targetQuota\nend\n\nfunction RoundService:GetSupermarketMap(): Model?\n    return workspace:FindFirstChild(\"SupermarketMap\") :: Model?\nend\n\n-- Teleports players to a target location\nlocal function teleportAllPlayers(targetCFrame: CFrame)\n    for _, player in ipairs(Players:GetPlayers()) do\n        local character = player.Character\n        if character and character.PrimaryPart then\n            character:PivotTo(targetCFrame + Vector3.new(math.random(-4, 4), 0, math.random(-4, 4)))\n        end\n    end\nend\n\n-- Unconditionally forces a state (used for initial startup or hard reset)\nfunction RoundService:ForceState(newState: Types.RoundState)\n    currentState = newState\n    self:ApplyStateLogic(newState)\nend\n\n-- Validates and applies state transition (rejects invalid transitions)\nfunction RoundService:SetState(newState: Types.RoundState): boolean\n    if currentState == newState then\n        return true\n    end\n\n    local allowed = VALID_TRANSITIONS[currentState]\n    if not allowed or not allowed[newState] then\n        warn(string.format(\"[RoundService] INVALID STATE TRANSITION REJECTED: %s -> %s\", currentState, newState))\n        return false\n    end\n\n    currentState = newState\n    self:ApplyStateLogic(newState)\n    return true\nend\n\nfunction RoundService:ApplyStateLogic(newState: Types.RoundState)\n    if newState == \"LOBBY\" then\n        stateTimer = Config.RoundTimers.LOBBY_DURATION\n        currentQuota = 0\n        targetQuota = 0\n        table.clear(playerContributions)\n\n    elseif newState == \"PREPARATION\" then\n        stateTimer = Config.RoundTimers.PREPARATION_DURATION\n        currentRoundId = Utility.GenerateUUID()\n        table.clear(playerContributions)\n\n        local playerCount = math.max(1, #Players:GetPlayers())\n        targetQuota = Config.QuotaConfig.BASE_QUOTA + (playerCount * Config.QuotaConfig.QUOTA_PER_PLAYER)\n        currentQuota = 0\n\n        disasterTimer = 0\n        nextDisasterInterval = math.random(Config.Disasters.IntervalMin, Config.Disasters.IntervalMax)\n\n        -- Populate initial tasks on supermarket floor\n        if services.TaskService then\n            services.TaskService:PopulateInitialTasks()\n        end\n\n        -- Teleport players to store entrance\n        teleportAllPlayers(CFrame.new(0, 3, -35))\n\n    elseif newState == \"ACTIVE\" then\n        stateTimer = Config.RoundTimers.MAIN_SHIFT_DURATION\n\n    elseif newState == \"CLOSING\" then\n        stateTimer = Config.RoundTimers.CLOSING_RUSH_DURATION\n\n    elseif newState == \"RESULTS\" then\n        stateTimer = Config.RoundTimers.RESULTS_DURATION\n        self:ProcessRoundResults()\n\n    elseif newState == \"RESET\" then\n        stateTimer = Config.RoundTimers.RESET_DURATION\n        self:CleanupRound()\n        -- Teleport players back to Lobby\n        teleportAllPlayers(CFrame.new(0, 3, -65))\n    end\n\n    self:BroadcastState()\n\n    if services.AnalyticsService then\n        services.AnalyticsService:LogEvent(\"RoundStateChanged\", {\n            State = newState,\n            RoundId = currentRoundId,\n        })\n    end\nend\n\n-- Broadcasts synchronized round state to all connected clients\nfunction RoundService:BroadcastState()\n    local remote = Network.GetRemoteEvent(Constants.Remotes.ROUND_STATE_CHANGED)\n    remote:FireAllClients(currentState, stateTimer, currentQuota, targetQuota)\nend\n\n-- Master authoritative clock tick\nfunction RoundService:Tick(deltaTime: number)\n    local players = Players:GetPlayers()\n    local playerCount = #players\n\n    if currentState == \"LOBBY\" then\n        if playerCount >= Config.ServerConfig.MIN_PLAYERS_TO_START then\n            stateTimer = math.max(0, stateTimer - deltaTime)\n            if stateTimer <= 0 then\n                self:SetState(\"PREPARATION\")\n            end\n        else\n            stateTimer = Config.RoundTimers.LOBBY_DURATION\n        end\n\n    elseif currentState == \"PREPARATION\" then\n        stateTimer = math.max(0, stateTimer - deltaTime)\n        if stateTimer <= 0 then\n            self:SetState(\"ACTIVE\")\n        end\n\n    elseif currentState == \"ACTIVE\" then\n        stateTimer = math.max(0, stateTimer - deltaTime)\n\n        -- Keep active tasks replenished if they run low\n        if services.TaskService and services.TaskService:GetActiveTaskCount() < 4 then\n            local map = self:GetSupermarketMap()\n            local taskAnchors = map and map:FindFirstChild(\"TaskAnchors\")\n            if taskAnchors then\n                local children = taskAnchors:GetChildren()\n                if #children > 0 then\n                    local randomAnchor = children[math.random(1, #children)]\n                    if randomAnchor:IsA(\"BasePart\") then\n                        local taskTypes = { \"CLEAN_SPILL\", \"RESTOCK\", \"DELIVER_ORDER\" }\n                        local pickedType = taskTypes[math.random(1, #taskTypes)]\n                        services.TaskService:CreateTask(pickedType, randomAnchor.Position, randomAnchor)\n                    end\n                end\n            end\n        end\n\n        -- Check disaster interval\n        disasterTimer = disasterTimer + deltaTime\n        if disasterTimer >= nextDisasterInterval then\n            disasterTimer = 0\n            nextDisasterInterval = math.random(Config.Disasters.IntervalMin, Config.Disasters.IntervalMax)\n            if services.DisasterService and not services.DisasterService:IsDisasterActive() then\n                local nextDisaster = services.DisasterService:SelectNextDisaster()\n                if nextDisaster then\n                    services.DisasterService:TriggerDisaster(nextDisaster)\n                end\n            end\n        end\n\n        if stateTimer <= 0 then\n            self:SetState(\"CLOSING\")\n        end\n\n    elseif currentState == \"CLOSING\" then\n        stateTimer = math.max(0, stateTimer - deltaTime)\n        if stateTimer <= 0 or currentQuota >= targetQuota then\n            self:SetState(\"RESULTS\")\n        end\n\n    elseif currentState == \"RESULTS\" then\n        stateTimer = math.max(0, stateTimer - deltaTime)\n        if stateTimer <= 0 then\n            self:SetState(\"RESET\")\n        end\n\n    elseif currentState == \"RESET\" then\n        stateTimer = math.max(0, stateTimer - deltaTime)\n        if stateTimer <= 0 then\n            self:SetState(\"LOBBY\")\n        end\n    end\n\n    self:BroadcastState()\nend\n\n-- Tracks team quota points and individual contribution\nfunction RoundService:AddQuotaProgress(points: number, contributingPlayer: Player?)\n    local multiplier = (currentState == \"CLOSING\") and Config.QuotaConfig.CLOSING_RUSH_MULTIPLIER or 1.0\n    local awardedPoints = math.floor(points * multiplier)\n\n    currentQuota = currentQuota + awardedPoints\n\n    if contributingPlayer then\n        local userId = contributingPlayer.UserId\n        if not playerContributions[userId] then\n            playerContributions[userId] = { TasksCompleted = 0, CreditsEarned = 0, XpEarned = 0 }\n        end\n        playerContributions[userId].TasksCompleted = playerContributions[userId].TasksCompleted + 1\n    end\n\n    self:BroadcastState()\nend\n\n-- Distributes end-of-shift rewards and produces results screen data\nfunction RoundService:ProcessRoundResults()\n    local isSuccess = currentQuota >= targetQuota\n    local teamBonus = isSuccess and 50 or 15\n\n    local mvpPlayerId: number? = nil\n    local maxTasks = -1\n\n    for userId, stats in pairs(playerContributions) do\n        if stats.TasksCompleted > maxTasks then\n            maxTasks = stats.TasksCompleted\n            mvpPlayerId = userId\n        end\n    end\n\n    local individualSummary: { [number]: any } = {}\n\n    for _, player in ipairs(Players:GetPlayers()) do\n        local stats = playerContributions[player.UserId] or { TasksCompleted = 0, CreditsEarned = 0, XpEarned = 0 }\n        local isMvp = (player.UserId == mvpPlayerId) and (stats.TasksCompleted > 0)\n        local finalCredits = teamBonus + (isMvp and 25 or 0)\n        local finalXp = isSuccess and 60 or 20\n\n        if services.EconomyService then\n            services.EconomyService:AwardCredits(player, finalCredits, \"ShiftResultBonus\")\n            services.EconomyService:AwardXp(player, finalXp, \"ShiftResultBonus\")\n        end\n\n        individualSummary[player.UserId] = {\n            PlayerName = player.Name,\n            TasksCompleted = stats.TasksCompleted,\n            CreditsEarned = finalCredits,\n            XpEarned = finalXp,\n            IsMvp = isMvp,\n        }\n    end\n\n    local resultsPayload: Types.RoundResultsData = {\n        Success = isSuccess,\n        ShiftName = \"Night Shift #\" .. string.sub(currentRoundId, -4),\n        QuotaReached = currentQuota,\n        QuotaTarget = targetQuota,\n        DurationSeconds = Config.RoundTimers.MAIN_SHIFT_DURATION + Config.RoundTimers.CLOSING_RUSH_DURATION - stateTimer,\n        TeamBonusCredits = teamBonus,\n        IndividualStats = individualSummary,\n    }\n\n    local remote = Network.GetRemoteEvent(Constants.Remotes.ROUND_RESULTS)\n    remote:FireAllClients(resultsPayload)\n\n    print(string.format(\"[RoundService] Shift %s concluded! Outcome: %s. Quota: %d/%d\", resultsPayload.ShiftName, isSuccess and \"SURVIVED\" or \"FAILED\", currentQuota, targetQuota))\nend\n\n-- Teardown of round instances\nfunction RoundService:CleanupRound()\n    if services.DisasterService then\n        services.DisasterService:StopActiveDisaster()\n    end\n    if services.TaskService then\n        services.TaskService:ClearAllTasks()\n    end\nend\n\nreturn RoundService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "TaskService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: TaskService.lua\n    Server-authoritative task manager. Dynamically spawns interactive physical tasks\n    (Restock, Spill, Delivery, Repair) at map anchors with ProximityPrompts,\n    performs atomic completion validation, and distributes rewards.\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal CollectionService = game:GetService(\"CollectionService\")\nlocal Workspace = game:GetService(\"Workspace\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nlocal TaskService = {\n    Name = \"TaskService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal activeTasks: { [string]: Types.TaskData } = {}\nlocal taskInstances: { [string]: Instance } = {}\nlocal rateLimiter: (key: any) -> boolean\nlocal activeTasksFolder: Folder\n\n-- Helper to create visual effects for physical tasks\nlocal function createPhysicalTaskVisual(taskData: Types.TaskData, parentFolder: Folder): Instance?\n    local taskDef = Config.Tasks[taskData.Type]\n    local holdDuration = taskDef and taskDef.InteractionDuration or 1.5\n\n    if taskData.Type == \"CLEAN_SPILL\" then\n        -- Slippery liquid puddle on floor\n        local puddle = Instance.new(\"Part\")\n        puddle.Name = \"Spill_\" .. taskData.Id\n        puddle.Shape = Enum.PartType.Cylinder\n        puddle.Size = Vector3.new(0.2, 7, 7) -- Cylinder height is X axis\n        puddle.CFrame = CFrame.new(taskData.Position + Vector3.new(0, 0.05, 0)) * CFrame.Angles(0, 0, math.rad(90))\n        puddle.Color = Color3.fromRGB(240, 70, 180) -- Toxic neon berry spill\n        puddle.Material = Enum.Material.Glass\n        puddle.Transparency = 0.25\n        puddle.Anchored = true\n        puddle.CanCollide = false\n        puddle.Parent = parentFolder\n\n        -- Sparkle / soap bubbles\n        local particles = Instance.new(\"ParticleEmitter\")\n        particles.Rate = 5\n        particles.Lifetime = NumberRange.new(1, 2)\n        particles.Speed = NumberRange.new(1, 3)\n        particles.Size = NumberSequence.new(0.4, 0.8)\n        particles.Color = ColorSequence.new(Color3.fromRGB(255, 200, 240))\n        particles.Parent = puddle\n\n        -- ProximityPrompt\n        local prompt = Instance.new(\"ProximityPrompt\")\n        prompt.ActionText = \"Mop Spill\"\n        prompt.ObjectText = \"Slippery Mess\"\n        prompt.HoldDuration = holdDuration\n        prompt.MaxActivationDistance = 10\n        prompt.RequiresLineOfSight = false\n        prompt.Parent = puddle\n\n        prompt.Triggered:Connect(function(player: Player)\n            TaskService:HandleTaskAction(player, taskData.Id, \"MOP\")\n        end)\n\n        return puddle\n\n    elseif taskData.Type == \"RESTOCK\" then\n        -- Empty shelf highlight\n        local boxMarker = Instance.new(\"Part\")\n        boxMarker.Name = \"Restock_\" .. taskData.Id\n        boxMarker.Size = Vector3.new(3.5, 2.5, 3.5)\n        boxMarker.CFrame = CFrame.new(taskData.Position)\n        boxMarker.Color = Color3.fromRGB(250, 200, 30)\n        boxMarker.Material = Enum.Material.Neon\n        boxMarker.Transparency = 0.55\n        boxMarker.Anchored = true\n        boxMarker.CanCollide = false\n        boxMarker.Parent = parentFolder\n\n        local prompt = Instance.new(\"ProximityPrompt\")\n        prompt.ActionText = \"Restock Shelf\"\n        prompt.ObjectText = \"Empty Shelf\"\n        prompt.HoldDuration = holdDuration\n        prompt.MaxActivationDistance = 10\n        prompt.RequiresLineOfSight = false\n        prompt.Parent = boxMarker\n\n        prompt.Triggered:Connect(function(player: Player)\n            TaskService:HandleTaskAction(player, taskData.Id, \"RESTOCK\")\n        end)\n\n        return boxMarker\n\n    elseif taskData.Type == \"REPAIR\" then\n        -- Malfunctioning breaker or cooler with electrical sparks\n        local repairMarker = Instance.new(\"Part\")\n        repairMarker.Name = \"Repair_\" .. taskData.Id\n        repairMarker.Size = Vector3.new(2, 2, 2)\n        repairMarker.CFrame = CFrame.new(taskData.Position)\n        repairMarker.Transparency = 1\n        repairMarker.Anchored = true\n        repairMarker.CanCollide = false\n        repairMarker.Parent = parentFolder\n\n        local sparks = Instance.new(\"ParticleEmitter\")\n        sparks.Rate = 18\n        sparks.Speed = NumberRange.new(5, 12)\n        sparks.Lifetime = NumberRange.new(0.2, 0.5)\n        sparks.SpreadAngle = Vector2.new(45, 45)\n        sparks.Color = ColorSequence.new(Color3.fromRGB(255, 230, 80))\n        sparks.Parent = repairMarker\n\n        local prompt = Instance.new(\"ProximityPrompt\")\n        prompt.ActionText = \"Repair Sparks\"\n        prompt.ObjectText = \"Faulty Breaker\"\n        prompt.HoldDuration = holdDuration\n        prompt.MaxActivationDistance = 10\n        prompt.RequiresLineOfSight = false\n        prompt.Parent = repairMarker\n\n        prompt.Triggered:Connect(function(player: Player)\n            TaskService:HandleTaskAction(player, taskData.Id, \"REPAIR\")\n        end)\n\n        return repairMarker\n\n    elseif taskData.Type == \"DELIVER_ORDER\" then\n        -- Delivery order at checkout conveyor\n        local ticketMarker = Instance.new(\"Part\")\n        ticketMarker.Name = \"Order_\" .. taskData.Id\n        ticketMarker.Size = Vector3.new(3, 0.4, 3)\n        ticketMarker.CFrame = CFrame.new(taskData.Position)\n        ticketMarker.Color = Color3.fromRGB(40, 220, 100)\n        ticketMarker.Material = Enum.Material.Neon\n        ticketMarker.Transparency = 0.4\n        ticketMarker.Anchored = true\n        ticketMarker.CanCollide = false\n        ticketMarker.Parent = parentFolder\n\n        local prompt = Instance.new(\"ProximityPrompt\")\n        prompt.ActionText = \"Deliver Groceries\"\n        prompt.ObjectText = \"Customer Order\"\n        prompt.HoldDuration = 1.0\n        prompt.MaxActivationDistance = 10\n        prompt.RequiresLineOfSight = false\n        prompt.Parent = ticketMarker\n\n        prompt.Triggered:Connect(function(player: Player)\n            TaskService:HandleTaskAction(player, taskData.Id, \"DELIVER\")\n        end)\n\n        return ticketMarker\n    end\n\n    return nil\nend\n\nfunction TaskService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\n    rateLimiter = Utility.CreateRateLimiter(Config.RateLimits.TASK_ACTION_MAX_PER_SECOND, 1.0)\n\n    -- Container for spawned task physical instances\n    local existing = Workspace:FindFirstChild(\"ActivePanicShiftTasks\")\n    if existing then\n        existing:Destroy()\n    end\n    activeTasksFolder = Instance.new(\"Folder\")\n    activeTasksFolder.Name = \"ActivePanicShiftTasks\"\n    activeTasksFolder.Parent = Workspace\nend\n\nfunction TaskService:Start()\n    local taskActionFunc = Network.GetRemoteFunction(Constants.Remotes.REQUEST_TASK_ACTION)\n    taskActionFunc.OnServerInvoke = function(player: Player, taskId: any, actionType: any): Types.NetworkResponse\n        return self:HandleTaskAction(player, taskId, actionType)\n    end\nend\n\n-- Populates initial tasks for a shift from the map's anchors\nfunction TaskService:PopulateInitialTasks()\n    self:ClearAllTasks()\n\n    local map = services.RoundService and services.RoundService:GetSupermarketMap()\n    if not map then\n        warn(\"[TaskService] Cannot populate tasks: SupermarketMap not found in Workspace!\")\n        return\n    end\n\n    local taskAnchors = map:FindFirstChild(\"TaskAnchors\")\n    if not taskAnchors then\n        warn(\"[TaskService] TaskAnchors folder not found in SupermarketMap!\")\n        return\n    end\n\n    -- 1. Spills (at least 3 spills)\n    local spillAnchors = {}\n    for _, child in ipairs(taskAnchors:GetChildren()) do\n        if child.Name:find(\"SpillAnchor\") and child:IsA(\"BasePart\") then\n            table.insert(spillAnchors, child)\n        end\n    end\n    for _, anchor in ipairs(spillAnchors) do\n        self:CreateTask(\"CLEAN_SPILL\", anchor.Position, anchor)\n    end\n\n    -- 2. Restocks (shelves needing boxes)\n    local restockAnchors = {}\n    for _, child in ipairs(taskAnchors:GetChildren()) do\n        if child.Name:find(\"RestockTarget\") and child:IsA(\"BasePart\") then\n            table.insert(restockAnchors, child)\n        end\n    end\n    for _, anchor in ipairs(restockAnchors) do\n        self:CreateTask(\"RESTOCK\", anchor.Position, anchor)\n    end\n\n    -- 3. Order Deliveries (checkouts)\n    local orderAnchors = {}\n    for _, child in ipairs(taskAnchors:GetChildren()) do\n        if child.Name:find(\"OrderDropTarget\") and child:IsA(\"BasePart\") then\n            table.insert(orderAnchors, child)\n        end\n    end\n    for idx = 1, math.min(2, #orderAnchors) do\n        local anchor = orderAnchors[idx]\n        self:CreateTask(\"DELIVER_ORDER\", anchor.Position, anchor)\n    end\n\n    -- 4. Repairs (breaker panels)\n    local maintenance = map:FindFirstChild(\"Maintenance\")\n    if maintenance then\n        local b1 = maintenance:FindFirstChild(\"BreakerPanel_1\")\n        if b1 and b1:IsA(\"BasePart\") then\n            self:CreateTask(\"REPAIR\", b1.Position + Vector3.new(1.5, 0, 0), b1)\n        end\n        local cooler = maintenance:FindFirstChild(\"CoolerUnit_2\")\n        if cooler and cooler:IsA(\"BasePart\") then\n            self:CreateTask(\"REPAIR\", cooler.Position + Vector3.new(-2, 0, 0), cooler)\n        end\n    end\n\n    print(string.format(\"[TaskService] Populated %d initial tasks for the shift.\", self:GetActiveTaskCount()))\nend\n\n-- Creates and spawns a single task instance\nfunction TaskService:CreateTask(taskType: Types.TaskType, position: Vector3, locationPart: BasePart?): Types.TaskData\n    local taskId = Utility.GenerateUUID()\n    local taskDef = Config.Tasks[taskType]\n\n    local taskData: Types.TaskData = {\n        Id = taskId,\n        Type = taskType,\n        Title = taskDef and taskDef.Name or \"Supermarket Task\",\n        LocationPart = locationPart,\n        Position = position,\n        IsActive = true,\n        IsCompleted = false,\n        AssignedPlayer = nil,\n        CreatedAt = os.clock(),\n        ExpiresAt = taskDef and taskDef.OrderTimeLimit and (os.clock() + taskDef.OrderTimeLimit) or nil,\n        Metadata = {},\n    }\n\n    activeTasks[taskId] = taskData\n\n    -- Spawn physical 3D interactive object\n    local visualInstance = createPhysicalTaskVisual(taskData, activeTasksFolder)\n    if visualInstance then\n        taskInstances[taskId] = visualInstance\n    end\n\n    -- Broadcast to clients\n    local remote = Network.GetRemoteEvent(Constants.Remotes.TASK_STATE_CHANGED)\n    remote:FireAllClients(taskId, \"CREATED\", {\n        Id = taskData.Id,\n        Type = taskData.Type,\n        Title = taskData.Title,\n        Position = taskData.Position,\n        ExpiresAt = taskData.ExpiresAt,\n    })\n\n    return taskData\nend\n\nfunction TaskService:GetActiveTaskCount(): number\n    local count = 0\n    for _, t in pairs(activeTasks) do\n        if t.IsActive and not t.IsCompleted then\n            count = count + 1\n        end\n    end\n    return count\nend\n\n-- Safely clears all currently active tasks\nfunction TaskService:ClearAllTasks()\n    for taskId, _ in pairs(activeTasks) do\n        local remote = Network.GetRemoteEvent(Constants.Remotes.TASK_STATE_CHANGED)\n        remote:FireAllClients(taskId, \"CLEARED\", nil)\n    end\n\n    for _, inst in pairs(taskInstances) do\n        if inst and inst.Parent then\n            inst:Destroy()\n        end\n    end\n\n    table.clear(activeTasks)\n    table.clear(taskInstances)\nend\n\n-- Validates and processes a player's interaction with a task\nfunction TaskService:HandleTaskAction(player: Player, taskId: any, actionType: any): Types.NetworkResponse\n    -- Anti-exploit: Rate limiting check\n    if not rateLimiter(player.UserId) then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.RATE_LIMITED, \"Interaction throttled.\")\n    end\n\n    -- Argument validation\n    if typeof(taskId) ~= \"string\" then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_ARGUMENTS, \"Invalid task ID.\")\n    end\n\n    local taskData = activeTasks[taskId]\n    if not taskData then\n        -- Resilient Fallback 1: match by LocationPart anchor name\n        for realId, data in pairs(activeTasks) do\n            if (data.LocationPart and data.LocationPart.Name == taskId) or data.Id == taskId then\n                taskData = data\n                taskId = realId\n                break\n            end\n        end\n    end\n\n    if not taskData then\n        -- Resilient Fallback 2: match closest active uncompleted task within range\n        local charPos = Utility.GetCharacterPosition(player.Character)\n        if charPos then\n            local closestDist = Constants.MAX_INTERACTION_DISTANCE\n            for realId, data in pairs(activeTasks) do\n                if data.IsActive and not data.IsCompleted then\n                    local dist = (data.Position - charPos).Magnitude\n                    if dist <= closestDist then\n                        closestDist = dist\n                        taskData = data\n                        taskId = realId\n                    end\n                end\n            end\n        end\n    end\n\n    if not taskData then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.TASK_NOT_FOUND, \"Task does not exist.\")\n    end\n\n    -- Atomic completion lock check (FR-09 / TEST-MP-01)\n    if taskData.IsCompleted then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.TASK_ALREADY_COMPLETED, \"Task was already completed by another employee.\")\n    end\n\n    if not taskData.IsActive then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_STATE, \"Task is no longer active.\")\n    end\n\n    -- Distance validation (FR-08 / TEST-SEC-02)\n    local charPos = Utility.GetCharacterPosition(player.Character)\n    if not charPos then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_STATE, \"Character position unknown.\")\n    end\n\n    if not Utility.IsWithinDistance(charPos, taskData.Position, Constants.MAX_INTERACTION_DISTANCE) then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.OUT_OF_RANGE, \"You are too far away from this task.\")\n    end\n\n    -- ATOMIC STATE MUTATION: Mark completed immediately to block race conditions\n    taskData.IsCompleted = true\n    taskData.IsActive = false\n\n    -- Remove physical world instance\n    local visual = taskInstances[taskId]\n    if visual and visual.Parent then\n        visual:Destroy()\n        taskInstances[taskId] = nil\n    end\n\n    local taskDef = Config.Tasks[taskData.Type]\n    local creditReward = taskDef and taskDef.CreditReward or 10\n    local xpReward = taskDef and taskDef.XpReward or 15\n    local quotaPoints = taskDef and taskDef.QuotaPoints or 1\n\n    -- Reward distribution\n    if services.EconomyService then\n        services.EconomyService:AwardCredits(player, creditReward, \"TaskCompletion_\" .. taskData.Type)\n        services.EconomyService:AwardXp(player, xpReward, \"TaskCompletion_\" .. taskData.Type)\n    end\n\n    -- Quota contribution\n    if services.RoundService then\n        services.RoundService:AddQuotaProgress(quotaPoints, player)\n    end\n\n    -- Daily challenge progress\n    if services.ChallengeService then\n        services.ChallengeService:IncrementProgress(player, \"DAILY_TASKS_10\", 1)\n        if taskData.Type == \"CLEAN_SPILL\" then\n            services.ChallengeService:IncrementProgress(player, \"DAILY_CLEAN_SPILLS_5\", 1)\n        end\n    end\n\n    -- Telemetry\n    if services.AnalyticsService then\n        services.AnalyticsService:LogEvent(\"TaskCompleted\", {\n            PlayerId = player.UserId,\n            TaskType = taskData.Type,\n            TaskId = taskId,\n        })\n    end\n\n    -- Broadcast completion to all clients\n    local remote = Network.GetRemoteEvent(Constants.Remotes.TASK_STATE_CHANGED)\n    remote:FireAllClients(taskId, \"COMPLETED\", {\n        CompletedBy = player.Name,\n    })\n\n    print(string.format(\"[TaskService] Player %s completed %s (+%d Credits, +%d XP, +%d Quota)\", player.Name, taskData.Type, creditReward, xpReward, quotaPoints))\n\n    return Utility.CreateSuccessResponse({\n        TaskId = taskId,\n        CreditsAwarded = creditReward,\n        XpAwarded = xpReward,\n        QuotaPoints = quotaPoints,\n    })\nend\n\nreturn TaskService\n")
return { batch = "batch3_services", count = 5, success = true }